```rust
/// Computes the Longest Common Subsequence (LCS) of two strings.
fn longest_common_subsequence(s1: &str, s2: &str) -> String {
    let s1_chars: Vec<char> = s1.chars().collect();
    let s2_chars: Vec<char> = s2.chars().collect();

    let m = s1_chars.len();
    let n = s2_chars.len();

    // Create DP table
    let mut dp = vec![vec![0; n + 1]; m + 1];

    // Fill DP table
    for i in 1..=m {
        for j in 1..=n {
            if s1_chars[i - 1] == s2_chars[j - 1] {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = dp[i - 1][j].max(dp[i][j - 1]);
            }
        }
    }

    // Reconstruct LCS by backtracking
    let mut lcs = String::new();
    let mut i = m;
    let mut j = n;

    while i > 0 && j > 0 {
        if s1_chars[i - 1] == s2_chars[j - 1] {
            lcs.push(s1_chars[i - 1]);
            i -= 1;
            j -= 1;
        } else if dp[i - 1][j] >= dp[i][j - 1] {
            i -= 1;
        } else {
            j -= 1;
        }
    }

    lcs.chars().rev().collect()
}

/// Returns the length of the LCS without constructing the string.
fn lcs_length(s1: &str, s2: &str) -> usize {
    let s1_chars: Vec<char> = s1.chars().collect();
    let s2_chars: Vec<char> = s2.chars().collect();

    let m = s1_chars.len();
    let n = s2_chars.len();

    let mut dp = vec![vec![0; n + 1]; m + 1];

    for i in 1..=m {
        for j in 1..=n {
            if s1_chars[i - 1] == s2_chars[j - 1] {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = dp[i - 1][j].max(dp[i][j - 1]);
            }
        }
    }

    dp[m][n]
}

fn main() {
    let s1 = "ABCBDAB";
    let s2 = "BDCABA";
    let lcs = longest_common_subsequence(s1, s2);
    println!("LCS of '{}' and '{}': '{}'", s1, s2, lcs);
    println!("LCS length: {}", lcs_length(s1, s2));
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_lcs() {
        assert_eq!(longest_common_subsequence("ABCBDAB", "BDCABA"), "BCAB");
        assert_eq!(lcs_length("ABCBDAB", "BDCABA"), 4);
    }

    #[test]
    fn test_no_common() {
        assert_eq!(longest_common_subsequence("ABC", "DEF"), "");
        assert_eq!(lcs_length("ABC", "DEF"), 0);
    }

    #[test]
    fn test_identical_strings() {
        assert_eq!(longest_common_subsequence("HELLO", "HELLO"), "HELLO");
        assert_eq!(lcs_length("HELLO", "HELLO"), 5);
    }

    #[test]
    fn test_one_empty() {
        assert_eq!(longest_common_subsequence("", "ABC"), "");
        assert_eq!(longest_common_subsequence("ABC", ""), "");
    }

    #[test]
    fn test_unicode_chars() {
        assert_eq!(longest_common_subsequence("你好世界", "你好"), "你好");
    }
}
```

### Key Features

- **Dynamic Programming**: Efficiently computes LCS using a 2D table.
- **Unicode Support**: Correctly handles multibyte characters using `chars()`.
- **Length-Only Variant**: Provides `lcs_length()` for performance-sensitive scenarios.
- **Robust Testing**: Includes test cases covering common, edge, and Unicode scenarios.

### Complexity

- **Time Complexity**: O(m × n), where m and n are the lengths of the input strings.
- **Space Complexity**: O(m × n) for the DP table.

This implementation is suitable for both learning and production use. For very large inputs, consider optimizing space with a rolling array approach.

