            grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
            gap: 20px;
            padding: 20px;
        }
        .product-card {
            border: 1px solid #ddd;
            border-radius: 8px;
            padding: 15px;
        }
        .product-image {
            width: 100%;
            height: 200px;
            object-fit: cover;
        }
        .out-of-stock {
            opacity: 0.6;
            position: relative;
        }
        .out-of-stock::after {
            content: "Out of Stock";
            position: absolute;
            top: 10px;
            right: 10px;
            background: #ff4444;
            color: white;
            padding: 5px 10px;
            border-radius: 4px;
        }
        .discount-badge {
            background: #28a745;
            color: white;
            padding: 3px 8px;
            border-radius: 4px;
            font-size: 12px;
        }
        .price {
            font-size: 18px;
            font-weight: bold;
            color: #333;
        }
        .original-price {
            text-decoration: line-through;
            color: #999;
            font-size: 14px;
            margin-left: 10px;
        }
    </style>
</head>
<body>
    <header>
        <h1>{{ page_title }}</h1>

        {% if filters %}
        <div class="filters">
            <h3>Filters</h3>
            <ul>
                {% for filter_name, filter_value in filters.items() %}
                <li>{{ filter_name }}: {{ filter_value }}</li>
                {% endfor %}
            </ul>
        </div>
        {% endif %}

        {% if sort_options %}
        <div class="sorting">
            <label for="sort">Sort by:</label>
            <select id="sort" onchange="location.href=this.value">
                {% for value, label in sort_options.items() %}
                <option value="{{ value }}" {% if current_sort == value %}selected{% endif %}>
                    {{ label }}
                </option>
                {% endfor %}
            </select>
        </div>
        {% endif %}
    </header>

    <main>
        {% if products %}
        <div class="product-grid">
            {% for product in products %}
            <article class="product-card {% if not product.in_stock %}out-of-stock{% endif %}">
                <img src="{{ product.image_url }}" alt="{{ product.name }}" class="product-image">

                <h2>{{ product.name }}</h2>

                {% if product.description %}
                <p class="description">{{ product.description[:100] }}{% if product.description|length > 100 %}...{% endif %}</p>
                {% endif %}

                <div class="pricing">
                    {% if product.on_sale %}
                    <span class="price">${{ product.price|round(2) }}</span>
                    <span class="original-price">${{ product.original_price|round(2) }}</span>
                    <span class="discount-badge">{{ product.discount_percentage }}% OFF</span>
                    {% else %}
                    <span class="price">${{ product.price|round(2) }}</span>
                    {% endif %}
                </div>

                <div class="stock-info">
                    {% if product.in_stock %}
                    <span>✅ In Stock ({{ product.stock_quantity }} available)</span>
                    {% else %}
                    <span>❌ Out of Stock</span>
                    {% endif %}
                </div>

                <div class="rating">
                    {% if product.rating %}
                    <span>⭐ {{ product.rating }}/5</span>
                    {% if product.review_count %}
                    ({{ product.review_count }} reviews)
                    {% endif %}
                    {% else %}
                    <span>No ratings yet</span>
                    {% endif %}
                </div>

                <a href="{{ product.url }}" class="btn">View Details</a>
            </article>
            {% endfor %}
        </div>

        {% else %}
        <div class="empty-state">
            <h2>No Products Found</h2>
            <p>Sorry, we couldn't find any products matching your criteria.</p>
            <a href="{{ homepage_url }}" class="btn">Browse All Products</a>
        </div>
        {% endif %}
    </main>

    {% if pagination %}
    <nav class="pagination">
        {% if pagination.has_prev %}
        <a href="{{ pagination.prev_url }}" class="btn">Previous</a>
        {% endif %}

        <span>Page {{ pagination.current_page }} of {{ pagination.total_pages }}</span>

        {% if pagination.has_next %}
        <a href="{{ pagination.next_url }}" class="btn">Next</a>
        {% endif %}

        {% if pagination.total_pages > 5 %}
        <ul class="page-numbers">
            {% for page_num in pagination.page_numbers %}
            <li>
                <a href="{{ pagination.get_page_url(page_num) }}" 
                   {% if page_num == pagination.current_page %}class="active"{% endif %}>
                    {{ page_num }}
                </a>
            </li>
            {% endfor %}
        </ul>
        {% endif %}
    </nav>
    {% endif %}

    {% if product_count %}
    <footer>
        <p>Showing {{ product_count }} of {{ total_products }} products</p>
    </footer>
    {% endif %}
</body>
</html>
```

## Key Jinja2 Features Used:

| Feature | Example | Purpose |
|---------|---------|---------|
| `{{ variable }}` | `{{ page_title }}` | Output variable values |
| `{% for %}` | `{% for product in products %}` | Loop through collections |
| `{% if %}` | `{% if product.in_stock %}` | Conditional logic |
| `{% else %}` | `{% else %}` | Alternative conditions |
| `{% endif %}` | `{% endif %}` | End conditional blocks |
| `{% endfor %}` | `{% endfor %}` | End loop blocks |
| `|round(2)` | `{{ product.price\|round(2) }}` | Filter for formatting |
| `{% if variable\|length > 100 %}` | String length check | Conditional based on length |

